document.addEventListener("DOMContentLoaded",(function(){const effectsController={init(){this.setupScrollTriggers()},setupScrollTriggers(){const scrollElements=document.querySelectorAll(".has-animation-effect.animation-trigger-onScroll");if(0===scrollElements.length)return;const observer=new IntersectionObserver(entries=>{entries.forEach(entry=>{entry.isIntersecting?entry.target.classList.add("animation-play"):(entry.target.classList.remove("animation-play"),entry.target.offsetHeight)})},{threshold:.4,rootMargin:"50px"});scrollElements.forEach(el=>observer.observe(el))}};effectsController.init()}));